-- Atualiza os 21 textos de compartilhamento (Módulo 1: Novo Convertido e
-- Módulo 2/3: Como Estudar a Bíblia) para terminarem com uma pergunta de
-- reflexão curta sobre o tema, além da referência bíblica "De acordo com...".

ALTER TABLE public.lesson_share_texts
  ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now();

ON CONFLICT (lesson_id) DO UPDATE SET
  lesson_title = EXCLUDED.lesson_title,
  share_text = EXCLUDED.share_text,
  updated_at = now();
